00043 class OlsHrdParams
00044 {
00045 private:
00046   bool     m_fixedPicRateGeneralFlag;
00047   bool     m_fixedPicRateWithinCvsFlag;
00048   uint32_t m_elementDurationInTcMinus1;
00049   bool     m_lowDelayHrdFlag;
00050 
00051   uint32_t m_bitRateValueMinus1[MAX_CPB_CNT][2];
00052   uint32_t m_cpbSizeValueMinus1[MAX_CPB_CNT][2];
00053   uint32_t m_ducpbSizeValueMinus1[MAX_CPB_CNT][2];
00054   uint32_t m_duBitRateValueMinus1[MAX_CPB_CNT][2];
00055   bool     m_cbrFlag[MAX_CPB_CNT][2];
00056 public:
00057   OlsHrdParams();
00058   virtual ~OlsHrdParams();
00059 
00060   void      setFixedPicRateGeneralFlag(bool flag) { m_fixedPicRateGeneralFlag = flag; }
00061   bool      getFixedPicRateGeneralFlag() const { return m_fixedPicRateGeneralFlag; }
00062   void      setFixedPicRateWithinCvsFlag(bool flag) { m_fixedPicRateWithinCvsFlag = flag; }
00063   bool      getFixedPicRateWithinCvsFlag() const { return m_fixedPicRateWithinCvsFlag; }
00064   void      setElementDurationInTcMinus1(uint32_t value) { m_elementDurationInTcMinus1 = value; }
00065   uint32_t  getElementDurationInTcMinus1() const { return m_elementDurationInTcMinus1; }
00066   void      setLowDelayHrdFlag(bool flag) { m_lowDelayHrdFlag = flag; }
00067   bool      getLowDelayHrdFlag() const { return m_lowDelayHrdFlag; }
00068   void      setBitRateValueMinus1(int cpbcnt, int nalOrVcl, uint32_t value) { m_bitRateValueMinus1[cpbcnt][nalOrVcl] = value; }
00069   uint32_t  getBitRateValueMinus1(int cpbcnt, int nalOrVcl) const { return m_bitRateValueMinus1[cpbcnt][nalOrVcl]; }
00070 
00071   void      setCpbSizeValueMinus1(int cpbcnt, int nalOrVcl, uint32_t value) { m_cpbSizeValueMinus1[cpbcnt][nalOrVcl] = value; }
00072   uint32_t  getCpbSizeValueMinus1(int cpbcnt, int nalOrVcl) const { return m_cpbSizeValueMinus1[cpbcnt][nalOrVcl]; }
00073   void      setDuCpbSizeValueMinus1(int cpbcnt, int nalOrVcl, uint32_t value) { m_ducpbSizeValueMinus1[cpbcnt][nalOrVcl] = value; }
00074   uint32_t  getDuCpbSizeValueMinus1(int cpbcnt, int nalOrVcl) const { return m_ducpbSizeValueMinus1[cpbcnt][nalOrVcl]; }
00075   void      setDuBitRateValueMinus1(int cpbcnt, int nalOrVcl, uint32_t value) { m_duBitRateValueMinus1[cpbcnt][nalOrVcl] = value; }
00076   uint32_t  getDuBitRateValueMinus1(int cpbcnt, int nalOrVcl) const { return m_duBitRateValueMinus1[cpbcnt][nalOrVcl]; }
00077   void      setCbrFlag(int cpbcnt, int nalOrVcl, bool value) { m_cbrFlag[cpbcnt][nalOrVcl] = value; }
00078   bool      getCbrFlag(int cpbcnt, int nalOrVcl) const { return m_cbrFlag[cpbcnt][nalOrVcl]; }
00079 };
