00081 class GeneralHrdParams
00082 {
00083 private:
00084   uint32_t m_numUnitsInTick;
00085   uint32_t m_timeScale;
00086   bool     m_generalNalHrdParamsPresentFlag;
00087   bool     m_generalVclHrdParamsPresentFlag;
00088   bool     m_generalSamePicTimingInAllOlsFlag;
00089   uint32_t m_tickDivisorMinus2;
00090   bool     m_generalDecodingUnitHrdParamsPresentFlag;
00091   uint32_t m_bitRateScale;
00092   uint32_t m_cpbSizeScale;
00093   uint32_t m_cpbSizeDuScale;
00094   uint32_t m_hrdCpbCntMinus1;
00095 
00096 public:
00097   GeneralHrdParams()
00098     :m_generalNalHrdParamsPresentFlag(false)
00099     ,m_generalVclHrdParamsPresentFlag(false)
00100     ,m_generalSamePicTimingInAllOlsFlag(true)
00101     ,m_tickDivisorMinus2                 (0)
00102     ,m_generalDecodingUnitHrdParamsPresentFlag  (false)
00103     ,m_bitRateScale                      (0)
00104     ,m_cpbSizeScale                      (0)
00105     ,m_cpbSizeDuScale                    (0)
00106     ,m_hrdCpbCntMinus1(0)
00107   {}
00108   bool operator==(const GeneralHrdParams& other) const
00109   {
00110     return (m_numUnitsInTick == other.m_numUnitsInTick
00111       && m_timeScale == other.m_timeScale
00112       && m_generalNalHrdParamsPresentFlag == other.m_generalNalHrdParamsPresentFlag
00113       && m_generalVclHrdParamsPresentFlag == other.m_generalVclHrdParamsPresentFlag
00114       && m_generalSamePicTimingInAllOlsFlag == other.m_generalSamePicTimingInAllOlsFlag
00115       && m_generalDecodingUnitHrdParamsPresentFlag == other.m_generalDecodingUnitHrdParamsPresentFlag
00116       && (m_generalDecodingUnitHrdParamsPresentFlag ? (m_tickDivisorMinus2 == other.m_tickDivisorMinus2): 1)
00117       && m_bitRateScale == other.m_bitRateScale
00118       && m_cpbSizeScale == other.m_cpbSizeScale
00119       && (m_generalDecodingUnitHrdParamsPresentFlag ? (m_cpbSizeDuScale == other.m_cpbSizeDuScale) : 1)
00120       && m_hrdCpbCntMinus1 == other.m_hrdCpbCntMinus1
00121       );
00122   }
00123 
00124   GeneralHrdParams& operator=(const GeneralHrdParams& input)
00125   {
00126     m_numUnitsInTick = input.m_numUnitsInTick;
00127     m_timeScale = input.m_timeScale;
00128     m_generalNalHrdParamsPresentFlag = input.m_generalNalHrdParamsPresentFlag;
00129     m_generalVclHrdParamsPresentFlag = input.m_generalVclHrdParamsPresentFlag;
00130     m_generalSamePicTimingInAllOlsFlag = input.m_generalSamePicTimingInAllOlsFlag;
00131     m_generalDecodingUnitHrdParamsPresentFlag = input.m_generalDecodingUnitHrdParamsPresentFlag;
00132     if (input.m_generalDecodingUnitHrdParamsPresentFlag)
00133     {
00134       m_tickDivisorMinus2 = input.m_tickDivisorMinus2;
00135     }
00136     m_bitRateScale = input.m_bitRateScale;
00137     m_cpbSizeScale = input.m_cpbSizeScale;
00138     if (input.m_generalDecodingUnitHrdParamsPresentFlag)
00139     {
00140       m_cpbSizeDuScale = input.m_cpbSizeDuScale;
00141     }
00142     m_hrdCpbCntMinus1 = input.m_hrdCpbCntMinus1;
00143     return *this;
00144   }
00145   virtual ~GeneralHrdParams() {}
00146   void      setNumUnitsInTick(uint32_t value) { m_numUnitsInTick = value; }
00147   uint32_t  getNumUnitsInTick() const { return m_numUnitsInTick; }
00148 
00149   void      setTimeScale(uint32_t value) { m_timeScale = value; }
00150   uint32_t  getTimeScale() const { return m_timeScale; }
00151 
00152   void      setGeneralNalHrdParametersPresentFlag(bool flag) { m_generalNalHrdParamsPresentFlag = flag; }
00153   bool      getGeneralNalHrdParametersPresentFlag() const { return m_generalNalHrdParamsPresentFlag; }
00154 
00155   void      setGeneralVclHrdParametersPresentFlag(bool flag) { m_generalVclHrdParamsPresentFlag = flag; }
00156   bool      getGeneralVclHrdParametersPresentFlag() const { return m_generalVclHrdParamsPresentFlag; }
00157 
00158   void      setGeneralSamePicTimingInAllOlsFlag(bool flag) { m_generalSamePicTimingInAllOlsFlag = flag; }
00159   bool      getGeneralSamePicTimingInAllOlsFlag() const { return m_generalSamePicTimingInAllOlsFlag; }
00160 
00161 
00162   void      setTickDivisorMinus2( uint32_t value )                                     { m_tickDivisorMinus2 = value;                               }
00163   uint32_t  getTickDivisorMinus2( ) const                                              { return m_tickDivisorMinus2;                                }
00164 
00165 
00166   void      setGeneralDecodingUnitHrdParamsPresentFlag( bool flag)                     { m_generalDecodingUnitHrdParamsPresentFlag = flag;                 }
00167   bool      getGeneralDecodingUnitHrdParamsPresentFlag( ) const                        { return m_generalDecodingUnitHrdParamsPresentFlag;                 }
00168 
00169   void      setBitRateScale( uint32_t value )                                          { m_bitRateScale = value;                                    }
00170   uint32_t  getBitRateScale( ) const                                                   { return m_bitRateScale;                                     }
00171 
00172   void      setCpbSizeScale( uint32_t value )                                          { m_cpbSizeScale = value;                                    }
00173   uint32_t  getCpbSizeScale( ) const                                                   { return m_cpbSizeScale;                                     }
00174   void      setCpbSizeDuScale( uint32_t value )                                        { m_cpbSizeDuScale = value;                                  }
00175   uint32_t  getCpbSizeDuScale( ) const                                                 { return m_cpbSizeDuScale;                                   }
00176 
00177   void      setHrdCpbCntMinus1(uint32_t value) { m_hrdCpbCntMinus1 = value; }
00178   uint32_t  getHrdCpbCntMinus1() const { return m_hrdCpbCntMinus1; }
00179 
00180 };
00181 
00182 inline void checkBPSyntaxElementLength(const SEIBufferingPeriod* bp1, const SEIBufferingPeriod* bp2)
00183 {
00184   CHECK(bp1->m_initialCpbRemovalDelayLength != bp2->m_initialCpbRemovalDelayLength ||
00185         bp1->m_cpbRemovalDelayLength != bp2->m_cpbRemovalDelayLength ||
00186         bp1->m_dpbOutputDelayLength != bp2->m_dpbOutputDelayLength ||
00187         bp1->m_duCpbRemovalDelayIncrementLength != bp2->m_duCpbRemovalDelayIncrementLength ||
00188         bp1->m_dpbOutputDelayDuLength != bp2->m_dpbOutputDelayDuLength,
00189         "All scalable-nested and non-scalable nested BP SEI messages in a CVS shall have the same value for "
00190         "each of the syntax elements bp_cpb_initial_removal_delay_length_minus1, bp_cpb_removal_delay_length_minus1, "
00191         "bp_dpb_output_delay_length_minus1, bp_du_cpb_removal_delay_increment_length_minus1, "
00192         "and bp_dpb_output_delay_du_length_minus1");
00193 }
00194 
00195 class HRD
00196 {
00197 public:
00198   HRD()
00199   :m_bufferingPeriodInitialized (false)
00200   , m_pictureTimingAvailable    (false) 
00201   {};
00202 
00203   virtual ~HRD()
00204   {};
00205   void                 setGeneralHrdParameters(GeneralHrdParams &generalHrdParam) { m_generalHrdParams = generalHrdParam; }
00206   GeneralHrdParams        getGeneralHrdParameters() const { return m_generalHrdParams; }
00207   const GeneralHrdParams& getGeneralHrdParameters() { return m_generalHrdParams; }
00208 
00209   void                 setOlsHrdParameters(int tLayter, OlsHrdParams &olsHrdParam) { m_olsHrdParams[tLayter] = olsHrdParam; }
00210   OlsHrdParams           getOlsHrdParameters(int idx) { return m_olsHrdParams[idx]; }
00211   OlsHrdParams*          getOlsHrdParametersAddr() { return m_olsHrdParams; }
00212   const OlsHrdParams&    getOlsHrdParameters(int idx) const { return m_olsHrdParams[idx]; }
00213 
00214   void                       setBufferingPeriodSEI(const SEIBufferingPeriod* bp)
00215   {
00216     if (m_bufferingPeriodInitialized)
00217     {
00218       checkBPSyntaxElementLength(bp, &m_bufferingPeriodSEI);
00219     }
00220     bp->copyTo(m_bufferingPeriodSEI); 
00221     m_bufferingPeriodInitialized = true;
00222   }
00223 
00224   const SEIBufferingPeriod*  getBufferingPeriodSEI() const                        { return m_bufferingPeriodInitialized ? &m_bufferingPeriodSEI : nullptr; }
00225 
00226   void                       setPictureTimingSEI(const SEIPictureTiming* pt)  { pt->copyTo(m_pictureTimingSEI); m_pictureTimingAvailable = true; }
00227   const SEIPictureTiming*    getPictureTimingSEI() const                      { return m_pictureTimingAvailable ? &m_pictureTimingSEI : nullptr; }
00228 
00229 protected:
00230   GeneralHrdParams      m_generalHrdParams;
00231   OlsHrdParams          m_olsHrdParams[MAX_TLAYER];
00232   bool               m_bufferingPeriodInitialized;
00233   SEIBufferingPeriod m_bufferingPeriodSEI;
00234   bool               m_pictureTimingAvailable;
00235   SEIPictureTiming   m_pictureTimingSEI;
00236 };
00237 
00238 } // namespace vtm
00239 
00240 #endif //__HRD__
